// src/routes/auth/login.ts
var login_default = withRoute(["POST"], async (request) => {
  const body = jsonBody(request);
  const email = requireEmail(body);
  const password = requirePassword(body);
  const user = await findUserByEmail(email);
  const invalid = new HttpError(401, "Incorrect email or password");
  if (user === null) throw invalid;
  if (!await verifyPassword(password, user.password_hash)) throw invalid;
  const profile = await findProfile(user.id) ?? await createProfile(user.id, user.email, "");
  const token = await signSessionToken({ userId: user.id, email: user.email });
  return { token, user: { id: user.id, email: user.email }, profile };
});

// src/routes/auth/me.ts
var me_default = withRoute(["GET"], async (request) => {
  const { userId } = await requireUser(request);
  const user = await findUserById(userId);
  if (user === null) throw notFound("User no longer exists");
  return { user, profile: await findProfile(userId) };
});

// src/routes/auth/register.ts
var register_default = withRoute(["POST"], async (request) => {
  const body = jsonBody(request);
  const email = requireEmail(body);
  const password = requirePassword(body);
  const fullName = requireString(body, "full_name", { max: 120 });
  const user = await createUser(email, await hashPassword(password));
  if (user === null) {
    throw conflict("An account with that email already exists");
  }
  const profile = await createProfile(user.id, email, fullName);
  const token = await signSessionToken({ userId: user.id, email: user.email });
  return { token, user, profile };
});

