// src/repositories/habits.ts
async function getOrCreateHabitLog(userId, logDate) {
  const row = await sqlOne`
    INSERT INTO habit_logs (user_id, log_date)
    VALUES (${userId}, ${logDate}::date)
    ON CONFLICT (user_id, log_date) DO UPDATE SET
      completed_habit_ids = habit_logs.completed_habit_ids
    RETURNING id, user_id, to_char(log_date, 'YYYY-MM-DD') AS log_date, completed_habit_ids
  `;
  if (row === null) throw new Error("Failed to load habit log");
  return row;
}
async function setCompletedHabitIds(userId, logDate, completedHabitIds) {
  const row = await sqlOne`
    INSERT INTO habit_logs (user_id, log_date, completed_habit_ids)
    VALUES (${userId}, ${logDate}::date, ${completedHabitIds})
    ON CONFLICT (user_id, log_date) DO UPDATE SET
      completed_habit_ids = EXCLUDED.completed_habit_ids
    RETURNING id, user_id, to_char(log_date, 'YYYY-MM-DD') AS log_date, completed_habit_ids
  `;
  if (row === null) throw new Error("Failed to save habit log");
  return row;
}
async function listRecentHabitLogs(userId, days) {
  const limit = Math.max(1, Math.min(days, 30));
  return sql`
    SELECT id, user_id, to_char(log_date, 'YYYY-MM-DD') AS log_date, completed_habit_ids
    FROM habit_logs
    WHERE user_id = ${userId}
      AND log_date >= (CURRENT_DATE - (${limit}::int - 1))
    ORDER BY log_date DESC
  `;
}

// src/routes/habits/history.ts
var history_default = withRoute(["GET"], async (request) => {
  const { userId } = await requireUser(request);
  const raw = request.query.days;
  const days = typeof raw === "string" ? Number.parseInt(raw, 10) : 7;
  const logs = await listRecentHabitLogs(userId, Number.isFinite(days) ? days : 7);
  return { logs };
});

// src/routes/habits/today.ts
var today_default = withRoute(["GET", "PUT"], async (request) => {
  const { userId } = await requireUser(request);
  if (request.method === "GET") {
    const date2 = requireDateKey(request.query.date);
    return getOrCreateHabitLog(userId, date2);
  }
  const body = jsonBody(request);
  const date = requireDateKey(body.date);
  const completedHabitIds = requireStringArray(body, "completed_habit_ids");
  return setCompletedHabitIds(userId, date, completedHabitIds);
});

