async function findInsights(userId) {
  const rows = await sql`
    SELECT user_id, payload, generated_at
    FROM insights
    WHERE user_id = ${userId}
  `;
  return rows[0] ?? null;
}
async function upsertInsights(userId, payload, generatedAt) {
  const row = await sqlOne`
    INSERT INTO insights (user_id, payload, generated_at)
    VALUES (${userId}, ${JSON.stringify(payload)}::jsonb, ${generatedAt})
    ON CONFLICT (user_id) DO UPDATE SET
      payload      = EXCLUDED.payload,
      generated_at = EXCLUDED.generated_at
    RETURNING user_id, payload, generated_at
  `;
  if (row === null) throw new Error("Failed to save insights");
  return row;
}

// src/routes/insights.ts
var insights_default = withRoute(["GET", "PUT"], async (request) => {
  const { userId } = await requireUser(request);
  if (request.method === "GET") {
    return findInsights(userId);
  }
  const body = jsonBody(request);
  const payload = requireObject(body, "payload");
  const generatedAt = optionalString(body, "generated_at") ?? (/* @__PURE__ */ new Date()).toISOString();
  return upsertInsights(userId, payload, generatedAt);
});

