var rf_default = withRoute(["GET"], async (request) => {
  const { userId } = await requireUser(request);
  const profile = await findProfile(userId);
  if (profile === null) throw new HttpError(404, "Profile not found");
  const insights = await findInsights(userId);
  const payloadInsights = insights?.payload;
  const context = {
    age: profile.age,
    gender: profile.gender,
    activityLevel: profile.activity_level,
    dietHabit: profile.diet_habit,
    smoking: profile.smoking,
    bmi: Number(profile.bmi),
    alcohol: profile.alcohol,
    sleepHours: Number(profile.sleep_hours),
    highBloodPressure: profile.high_blood_pressure
  };
  if (typeof payloadInsights?.healthAge === "number") {
    context.healthAge = payloadInsights.healthAge;
  }
  const rf = recommendHabitsWithRandomForest(context, 4);
  const habits = rf.habits.map((h) => {
    const meta = habitMeta(h.id, context);
    const reason = reasonForHabit(h.id, context);
    return {
      id: h.id,
      title: meta.title,
      title_bm: meta.title_bm,
      title_zh: meta.title_zh,
      category: meta.category,
      score: h.score,
      reason: reason.en,
      reason_bm: reason.bm,
      reason_zh: reason.zh
    };
  });
  return {
    habits,
    coach_note: "Your 4 actions are personalised from your questionnaire answers and health profile.",
    coach_note_bm: "4 tindakan anda diperibadikan daripada jawapan soal selidik dan profil kesihatan anda.",
    coach_note_zh: "\u60A8\u7684 4 \u9879\u884C\u52A8\u6839\u636E\u95EE\u5377\u56DE\u7B54\u4E0E\u5065\u5EB7\u8D44\u6599\u4E2A\u6027\u5316\u751F\u6210\u3002"
  };
});

// src/vercelEntry.ts
async function health(_request, response) {
  const payload = {
    status: "ok",
    database: "skipped",
    time: null
  };
  const databaseUrl = process.env.DATABASE_URL;
  if (typeof databaseUrl === "string" && databaseUrl.trim() !== "") {
    try {
      const { neon } = await Promise.resolve().then(() => (init_serverless(), serverless_exports));
      const url = databaseUrl.replace(/([?&])channel_binding=[^&]*&?/i, "$1").replace(/[?&]$/, "");
      const sql2 = neon(url);
      const rows = await sql2`SELECT now() AS now`;
      payload.database = "ok";
      payload.time = rows[0]?.now ?? null;
    } catch (error) {
      const message2 = error instanceof Error ? error.message : "database error";
      console.error("health database check failed:", message2);
      payload.status = "degraded";
      payload.database = "unreachable";
      payload.error = "database query failed";
    }
  } else {
    payload.status = "degraded";
    payload.database = "unreachable";
    payload.error = "DATABASE_URL missing";
  }
  response.status(200).json(payload);
}
